package com.wtm.importer;
import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
public final class DamageKpiProfile implements KpiCsvImportProfile{public boolean supports(CsvTable t){boolean d=has(t,"date","damagedate","eventdate","completeddate");boolean e=has(t,"employee","employeenumber","shortname","user","username","completeduser","completeduserbk","causedby");boolean x=t.headers().stream().anyMatch(h->h.contains("damage"));return d&&e&&x;}public KpiImportResult parse(CsvTable t)throws Exception{TreeMap<LocalDate,Integer>d=new TreeMap<>();List<String>w=new ArrayList<>();for(Map<String,String>r:t.rows()){LocalDate x=date(first(r,"date","damagedate","eventdate","completeddate"));if(x==null){w.add("Skipped a damage row with an invalid date.");continue;}d.merge(x,1,Integer::sum);}if(d.isEmpty())throw new IllegalArgumentException("No dated damage records could be imported.");List<KpiImportedMetric>h=new ArrayList<>();for(var e:d.entrySet())h.add(new KpiImportedMetric("damages","Damages",e.getValue(),"",e.getKey(),"CSV_DAMAGES"));LocalDate l=d.lastKey();return new KpiImportResult("Damages",t.rows().size(),d.firstKey(),l,List.of(new KpiImportedMetric("damages","Damages",d.get(l),"",l,"CSV_DAMAGES")),h,w);}static boolean has(CsvTable t,String...n){for(String x:n)if(t.headers().contains(CsvTable.normalize(x)))return true;return false;}static String first(Map<String,String>r,String...n){for(String x:n){String v=r.get(CsvTable.normalize(x));if(v!=null&&!v.isBlank())return v;}return "";}static LocalDate date(String r){if(r==null||r.isBlank())return null;String v=r.trim();try{if(v.length()>=10)return LocalDate.parse(v.substring(0,10));}catch(Exception ignored){}for(DateTimeFormatter f:List.of(DateTimeFormatter.ofPattern("M/d/uuuu"),DateTimeFormatter.ofPattern("M-d-uuuu"))){try{return LocalDate.parse(v,f);}catch(Exception ignored){}}return null;}}